/**
 * Thin wrapper over chrome.i18n. Every user-facing string comes from public/_locales at runtime
 * (generated by scripts/locales.mjs), so nothing translated is ever inlined into the bundles.
 * Safe where chrome.i18n does not exist (node tests, odd contexts): a missing message returns the key.
 */
export type Sub = string | number | ReadonlyArray<string | number>;

export function t(key: string, sub?: Sub): string {
  try {
    const subs = sub === undefined ? undefined : (Array.isArray(sub) ? sub : [sub]).map(String);
    const m = chrome.i18n.getMessage(key, subs);
    return m || key;
  } catch {
    return key;
  }
}

/** One entry per message: a bare key, or [key, ...substitutions]. */
export type KeyItem = string | readonly [string, ...Array<string | number>];

/** Renders a list of message keys (signals, alerts, finding lines) to plain strings. */
export function tAll(items: readonly KeyItem[]): string[] {
  return items.map((it) => (typeof it === "string" ? t(it) : t(it[0], it.slice(1) as Array<string | number>)));
}

/** Translate every element carrying data-i18n / data-i18n-title / data-i18n-placeholder / data-i18n-aria in a static page. */
export function localizePage(root: ParentNode = document): void {
  for (const el of root.querySelectorAll<HTMLElement>("[data-i18n]")) {
    el.textContent = t(el.dataset.i18n!);
  }
  for (const el of root.querySelectorAll<HTMLElement>("[data-i18n-title]")) {
    el.title = t(el.dataset.i18nTitle!);
  }
  for (const el of root.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("[data-i18n-placeholder]")) {
    el.placeholder = t(el.dataset.i18nPlaceholder!);
  }
  for (const el of root.querySelectorAll<HTMLElement>("[data-i18n-aria]")) {
    el.setAttribute("aria-label", t(el.dataset.i18nAria!));
  }
  try {
    document.documentElement.lang = chrome.i18n.getUILanguage();
  } catch {
    /* ignore */
  }
}
